shader:
// Whip Pan - handheld camera whip with the cut hidden at peak speed.
// One continuous virtual camera: A ramps up hard (quartic ease-in) into a pure streak; the cut sits inside the
// shutter of the fastest frame, where B sweeps in from its own side already streaking; B then brakes hard
// (quartic ease-out), overshoots rest a little and eases back like an operator catching the frame.
// Every blur tap is a real moment of the camera path (offset + roll + push-in + arc + depth parallax), taps are
// averaged in linear light so highlights streak like a real exposure, the A -> B switch inside the shutter is a
// short soft fade (no sharp streak ends), taps are packed toward the middle of the shutter (importance sampled)
// and the comb is shifted per pixel with interleaved gradient noise: no ghost copies, only a very fine grain.
// params: angle (deg, 0 = picture flies to the left, 90 = up), blur (shutter / streak length),
//         tilt (deg of camera roll at the peak), settle (landing overshoot, 0 = none)

const int WP_TAPS = 36;            // + at most 11 dual-sampled taps in the soft switch = 47 fetches worst case
const float WP_CUT = 0.5;
const float WP_PI = 3.14159265;
const float WP_SOFT = 5.5;         // half-width of the in-shutter A -> B fade, in taps
const float WP_WARP = 0.3;         // tap packing toward the shutter middle (weights are corrected for it)
const float WP_FOLD = 0.06;        // depth (uv) at which samples that leave the frame stop and smear

// interleaved gradient noise: well spread per-pixel comb offsets (the grain sits at the finest spatial frequency)
float wpIgn(vec2 p) {
    return fract(52.9829189 * fract(dot(p, vec2(0.06711056, 0.00583715))));
}

// soft fold for samples that leave the frame: right at the edge it is the plain mirror (seamless for the small
// overshoots of roll / settle); further out the mirrored point slows down and stops ~WP_FOLD inside the frame, so
// the content entering beyond the edge is a smear of the edge band instead of a mirrored copy running backwards
// (no ghost pillar / double band on the trailing side)
vec2 wpFold(vec2 s) {
    vec2 hi = max(s - 1.0, 0.0);
    vec2 lo = max(-s, 0.0);
    return clamp(s, 0.0, 1.0) - WP_FOLD * (1.0 - exp(-hi / WP_FOLD)) + WP_FOLD * (1.0 - exp(-lo / WP_FOLD));
}

// shutter time 0..1 of comb position g 0..1 (denser in the middle, where the shutter weight is high)
float wpWarp(float g) {
    return g + WP_WARP * sin(2.0 * WP_PI * g) / (2.0 * WP_PI);
}

// camera travel 0 -> 1 (A owns 0..0.5, B owns 0.5..1): quartic ease-in into the cut, quartic ease-out after it,
// velocity peaks at the cut; after the cut B overshoots rest by ~2.4% of the frame (settle = 1) and eases back,
// arriving with zero velocity and zero acceleration, so the clip after the transition continues without a bump
float wpTravel(float t) {
    t = clamp(t, 0.0, 1.0);
    if (t < WP_CUT) {
        float u = t / WP_CUT;
        return 0.5 * u * u * u * u;
    }
    float s = (t - WP_CUT) / (1.0 - WP_CUT);        // 0 at the cut .. 1 at rest
    float r = 1.0 - s;
    float sr = s * r;
    return 1.0 - 0.5 * r * r * r * r + 3.0 * settle * sr * sr * sr;
}

vec4 transition(vec2 uv) {
    // at progress 0 / 1 the shutter is closed (W = 0) and the camera is at rest, so this is exactly A / B
    float a = radians(angle);
    vec2 dir = vec2(-cos(a), sin(a));               // where the picture travels
    vec2 nrm = vec2(-dir.y, dir.x);
    vec2 asp = vec2(ratio, 1.0);
    float ext = abs(dir.x) * ratio + abs(dir.y);    // frame size along the move (height units)
    float extN = abs(nrm.x) * ratio + abs(nrm.y);
    vec2 P = (uv - 0.5) * asp;
    float along = dot(P, dir) / ext;                // -0.5 (side B enters from) .. 0.5 (side A leaves to)

    // shutter window in progress units, opens up only once the camera moves; around the cut it never drops below
    // a full streak (a low blur setting stays crisper in the ramps but the cut is still hidden) and it is 15%
    // shorter right at the peak, which keeps the fastest frame's grain level with its neighbours
    float dCut = abs(progress - WP_CUT);
    float env = smoothstep(0.0, 0.12, progress) * smoothstep(0.0, 0.12, 1.0 - progress);
    float nearCut = 1.0 - smoothstep(0.02, 0.11, dCut);
    float W = 0.085 * env * mix(blur, max(blur, 1.0), nearCut) * (0.85 + 0.15 * smoothstep(0.0, 0.09, dCut));
    // inside the shutter of the cut frames B sweeps in from its own side
    float cutAt = WP_CUT + 1.8 * W * along;
    // where the cut falls inside this pixel's shutter, as a comb position in tap units (fractional -> no banding)
    float fc = clamp((cutAt - (progress - W)) / max(2.0 * W, 1e-6), -1.0, 2.0);
    float gc = fc;
    for (int n = 0; n < 3; n++) {
        gc -= (wpWarp(gc) - fc) / (1.0 + WP_WARP * cos(2.0 * WP_PI * gc));
    }
    float xc = gc * float(WP_TAPS);
    // per-pixel shift of the whole comb, re-rolled every frame -> fine grain instead of ghost copies
    float jit = wpIgn(floor(uv * resolution) + 61.0 * floor(time * 60.0));
    float rollMax = radians(tilt);
    float travelLen = 0.85 * ext;

    vec4 acc = vec4(0.0);
    float wsum = 0.0;
    for (int i = 0; i < WP_TAPS; i++) {
        float fk = float(i) + jit;
        float g = fk / float(WP_TAPS);
        float fj = wpWarp(g);                                // sample time inside the shutter, 0..1
        float tj = progress + W * (2.0 * fj - 1.0);
        float shA = 1.0 - smoothstep(xc - WP_SOFT, xc + WP_SOFT, fk);   // share of A in this tap

        // handheld extras follow each clip's own closeness to the cut and keep growing through it (no cusp,
        // so the cut frame is never crisper than its neighbours); roll builds and settles gently (^2), the
        // vertical arc and push-in only kick in near the peak (^4), so the ramps read as a clean sideways whip
        float uu = mix(min(tj / WP_CUT, 1.35), min((1.0 - tj) / (1.0 - WP_CUT), 1.35), 1.0 - shA);
        float bump = uu * uu;
        float bumpV = bump * bump;
        float tr = wpTravel(tj);
        float roll = rollMax * bump;
        float par = 1.0 - 0.10 * bump * P.y;                 // lower (closer) part travels a bit further
        vec2 q = P / (1.0 + 0.03 * bumpV);                   // slight push-in at the peak
        float cr = cos(roll);
        float sr = sin(roll);
        q = vec2(cr * q.x - sr * q.y, sr * q.x + cr * q.y);
        q -= nrm * (0.015 * extN * bumpV);                   // slight arc across the move
        vec2 stepv = dir * (travelLen * par) / asp;
        vec2 sA = q / asp + 0.5 - stepv * tr;                // A: travel 0 -> 0.5
        vec2 sB = sA + stepv;                                // B: travel - 1 = -0.5 -> 0 (+ settle)

        float sw = sin(WP_PI * fj);
        // smooth shutter (no box edges, no hard streak ends), divided by the tap density of the warp
        float w = (0.06 + sw * sw) * (1.0 + WP_WARP * cos(2.0 * WP_PI * g));
        vec4 c;
        if (shA >= 1.0) {
            c = getA(wpFold(sA));
            c.rgb *= c.rgb;
        } else if (shA <= 0.0) {
            c = getB(wpFold(sB));
            c.rgb *= c.rgb;
        } else {
            vec4 ca = getA(wpFold(sA));
            vec4 cb = getB(wpFold(sB));
            c = mix(vec4(cb.rgb * cb.rgb, cb.a), vec4(ca.rgb * ca.rgb, ca.a), shA);
        }
        acc += c * w;                                        // linear-light accumulation (gamma 2)
        wsum += w;
    }
    acc /= wsum;
    return vec4(sqrt(acc.rgb), acc.a);
}
